import { MeshPhysicalNodeMaterial, CylinderGeometry, OctahedronGeometry, PlaneGeometry, Mesh, Group, DirectionalLight, Color } from 'three/webgpu';
import { vec3, vec4, float, uniform, normalWorld, cameraPosition, viewDirection, dot, mix, atan, sin, cos, abs, smoothstep, color, positionWorld, uv, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Prism ---
  // Equilateral triangle side 1.2, height 1.8
  const prismGeo = new CylinderGeometry(0.693, 0.693, 1.8, 3);
  // Rotate to align axis along X
  prismGeo.rotateZ(-Math.PI / 2);
  // Apply spec rotations: 12 deg on z, 20 deg on y (already in group? We'll apply to mesh directly)
  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    color: 0xffffff,
    envMapIntensity: 1.0,
    side: 2, // DoubleSide
  });

  // Dispersion pass: chromatic shift based on angle
  const angle = dot(normalWorld, normalize(cameraPosition.sub(positionWorld)));
  const dispersion = uniform(0.18); // 0.18 across RGB -> per channel offset ~0.06
  const rOffset = mix(float(0), dispersion, angle).mul(0.06);
  const bOffset = mix(float(0), dispersion.negate(), angle).mul(0.06);
  // Get material's built-in base color (white) and apply shift
  const baseColor = prismMat.colorNode || vec3(1);
  const r = baseColor.r.add(rOffset);
  const g = baseColor.g;
  const b = baseColor.b.add(bOffset);
  prismMat.colorNode = vec3(r, g, b);

  const prism = new Mesh(prismGeo, prismMat);
  prism.rotation.set(0, 0.349, 0.209); // 20 deg y, 12 deg z (radians)
  group.add(prism);

  // --- Emissive core (octahedron) ---
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    roughness: 0.3,
    metalness: 0.0,
  });
  const core = new Mesh(coreGeo, coreMat);
  core.position.set(0, 0, 0);
  group.add(core);

  // --- Caustic streak (plane on floor) ---
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  // Gradient node with dispersed colours
  const uvNode = uv();
  const gradientPos = uvNode.y; // 0 bottom to 1 top
  const redStop = float(0.2);
  const whiteStop = float(0.5);
  const blueStop = float(0.8);
  const colorA = color('#ff2a38');
  const colorB = color('#e8ecf2');
  const colorC = color('#9fb0c4');
  const mixed1 = mix(colorA, colorB, smoothstep(redStop, whiteStop, gradientPos));
  const mixed2 = mix(mixed1, colorC, smoothstep(whiteStop, blueStop, gradientPos));
  const causticMat = new MeshBasicNodeMaterial({
    colorNode: mixed2,
    transparent: true,
    opacity: 0.35,
    side: 2,
  });
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0);
  group.add(caustic);

  // --- Back rim light ---
  const rimLight = new DirectionalLight(0xe8ecf2, 1.2);
  rimLight.position.set(-2, 0.5, 2); // behind-left
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // --- Text content ---
  const headline = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.5,
  });
  headline.position.set(0, -1.75, 0);
  group.add(headline);

  const caption = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 1.44, // 0.08em
  });
  caption.position.set(0, -2.25, 0); // 0.5 below headline baseline
  group.add(caption);

  // --- Cinematic primitive: depth-rotate on hover ---
  let depthCleanup = null;
  if (config.cinematicPrimitives && config.cinematicPrimitives.length) {
    // Apply each primitive; spec expects depth-rotate with hover trigger
    config.cinematicPrimitives.forEach((prim) => {
      if (prim.name === 'depth-rotate' && prim.trigger === 'hover') {
        const result = ctx.primitives['depth-rotate'](group, prim.params);
        if (result) depthCleanup = result.cleanup;
      }
    });
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (depthCleanup) depthCleanup();
    // Dispose geometries
    prismGeo.dispose();
    coreGeo.dispose();
    causticGeo.dispose();
    // Dispose materials
    prismMat.dispose();
    coreMat.dispose();
    causticMat.dispose();
    // Remove lights? No need.
    // Kill any GSAP timelines created by primitives (handled by primitive cleanup)
  };

  return group;
}
